// Species database wrapper: types, lookup, provenance. The numbers live in species.gen.ts (generated by
// scripts/port-thermo.py from docs/research); nothing here retypes a coefficient.
import type { Conf } from '../sim/types';
import { SPECIES_GEN, SPECIES_GEN_ORDER } from './species.gen';

export type Phase = 'g' | 'l' | 's' | 's/l' | 'aq';
export type SegmentKind = 'shomate' | 'nasa7' | 'constcp';

/** One heat-capacity polynomial. shomate: [A..H] (NIST, kJ/mol basis); nasa7: [a1..a7]; constcp: [H298 kJ/mol, S298, Cp]. */
export interface ThermoSegment {
  kind: SegmentKind;
  Tlo: number;
  Thi: number;
  coef: readonly number[];
  /** True when the segment starts at a real phase change (latent-heat step), not at a polynomial junction. */
  phaseChange?: boolean;
}

export interface AntoineRec { A: number; B: number; C: number; Tlo: number; Thi: number }

/** A catalogue species (plain JSON). Units of the stored numbers: kJ/mol, J/(mol K), g/mol, K; `Pc` is in Pa. */
export interface SpeciesRec {
  id: string;
  name: string;
  formula: string;
  elements: Readonly<Record<string, number>>;
  /** Molar mass, g/mol (computed from the element vector with IUPAC 2021 weights). */
  M: number;
  phase: Phase;
  /** 'must' = DESIGN 10.1 must-ship; 'stretch' = ships only if ready. */
  tier: 'must' | 'stretch';
  /** False for lab/lumped pseudo-species that only carry a molar mass. */
  hasThermo: boolean;
  /** dHf (298.15 K), kJ/mol. */
  dHf298?: number;
  /** S (298.15 K), J/(mol K). Absent for molar-mass-only pseudo-species. */
  S298?: number;
  segments: readonly ThermoSegment[];
  /** Liquids without a polynomial: the gas whose h is lowered by dHvap(T) (Watson). */
  liquidOf?: string;
  Tb?: number;
  Tc?: number;
  /** Pa. */
  Pc?: number;
  omega?: number;
  /** J/mol at Tb. */
  dHvapTb?: number;
  antoine?: AntoineRec;
  colour: string;
  colourSrc: 'DESIGN5.6' | 'GAME';
  janaf?: string;
  src: string;
  conf: Conf;
  confCrit?: Conf;
  confTb?: Conf;
  confAntoine?: Conf;
  confDHvap?: Conf;
  notes: string;
}

interface GenRec extends Omit<SpeciesRec, 'Pc' | 'dHvapTb'> {
  Pc_bar?: number;
  dHvapTb_kJ?: number;
}

/** CODATA / IUPAC constants shared by the thermo code. */
export const R_GAS = 8.314462618;
export const T_REF = 298.15;
export const P_STD = 1e5;

/** IUPAC 2021 conventional (abridged) standard atomic weights, g/mol (DESIGN 3.2) plus the fractional-element helper. */
export const ATOMIC_WEIGHT: Readonly<Record<string, number>> = { H: 1.008, C: 12.011, N: 14.007, O: 15.999, S: 32.06, Cl: 35.45, Na: 22.99, Ar: 39.95 };

export function molarMassOf(elements: Readonly<Record<string, number>>): number {
  let m = 0;
  for (const e of Object.keys(elements)) m += ATOMIC_WEIGHT[e]! * elements[e]!;
  return m;
}

function build(): Record<string, SpeciesRec> {
  const out: Record<string, SpeciesRec> = {};
  const gen = SPECIES_GEN as unknown as Record<string, GenRec>;
  for (const id of SPECIES_GEN_ORDER) {
    const g = gen[id]!;
    const { Pc_bar, dHvapTb_kJ, ...rest } = g;
    const rec: SpeciesRec = { ...rest };
    if (Pc_bar !== undefined) rec.Pc = Pc_bar * 1e5;
    if (dHvapTb_kJ !== undefined) rec.dHvapTb = dHvapTb_kJ * 1000;
    out[id] = rec;
  }
  return out;
}

export const SPECIES: Readonly<Record<string, SpeciesRec>> = build();
export const SPECIES_IDS: readonly string[] = SPECIES_GEN_ORDER;
export const MUST_SHIP: readonly string[] = SPECIES_IDS.filter((id) => SPECIES[id]!.tier === 'must');

export function findSpecies(id: string): SpeciesRec | undefined { return Object.prototype.hasOwnProperty.call(SPECIES, id) ? SPECIES[id] : undefined; }

/** Atom matrix A[e][i] = atoms of element e in species ids[i]; `elements` lists the rows (sorted). */
export function atomMatrix(ids: readonly string[]): { elements: string[]; A: number[][] } {
  const set = new Set<string>();
  for (const id of ids) for (const e of Object.keys(SPECIES[id]!.elements)) set.add(e);
  const elements = [...set].sort();
  const A = elements.map((e) => ids.map((id) => SPECIES[id]!.elements[e] ?? 0));
  return { elements, A };
}

export interface ProvenanceRow {
  id: string;
  tier: 'must' | 'stretch';
  src: string;
  conf: Conf;
  confCrit?: Conf;
  confTb?: Conf;
}

/** One row per species for the provenance test and the Codex data page. */
export function provenanceReport(): ProvenanceRow[] {
  return SPECIES_IDS.map((id) => {
    const s = SPECIES[id]!;
    return { id, tier: s.tier, src: s.src, conf: s.conf, confCrit: s.confCrit, confTb: s.confTb };
  });
}
